package com.graduation.library.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(BookRepository books){return args->{if(books.count()==0){var x=new Book();x.setIsbn("9787115428028");x.setTitle("深入理解计算机系统");x.setAuthor("Randal E. Bryant / David R. O'Hallaron");x.setPublisher("机械工业出版社");x.setCategory("计算机");x.setTotalCopies(5);x.setAvailableCopies(5);x.setDescription("从程序员视角理解计算机系统");x.setStatus("AVAILABLE");books.save(x);}};}}
